def render_cookie_report(result, language='en'):
    messages = TEXT.get(language, TEXT['en'])
    def msg(code):
        return messages.get(code, messages['unknown_error'])
    local = result.file
    lines = [msg('title'), msg(local.code)]
    if local.total:
        lines.append(msg('stats').format(total=local.total, active=local.active, expired=local.expired))
    if local.line:
        lines.append(msg('line').format(line=local.line))
    if local.code == 'source_fetch_failed':
        lines.extend(('', msg('source_request') + ': ' + msg(result.video)))
    if local.code == 'ready':
        lines.extend(('', msg('login') + ': ' + msg(result.auth),
                      '', msg('video') + ': ' + msg(result.video)))
        if local.auth_expired:
            lines.extend(('', msg('auth_expiry_note')))
    return '\n'.join(lines)
